package es.idynamicsax.ostris.service;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import es.idynamicsax.ostris.core.JournalTransaction;
import es.idynamicsax.ostris.core.OstrisAmount;
import es.idynamicsax.ostris.core.OstrisWireCodec;
import es.idynamicsax.ostris.core.ProtocolException;
import es.idynamicsax.ostris.core.ResolutionBasisType;
import es.idynamicsax.ostris.core.TransactionEntry;
import es.idynamicsax.ostris.core.TransactionPurpose;
import es.idynamicsax.ostris.core.TransactionValidator;
import es.idynamicsax.ostris.persistence.AccountEntity;
import es.idynamicsax.ostris.persistence.AccountRepository;
import es.idynamicsax.ostris.persistence.CommunityEntity;
import es.idynamicsax.ostris.persistence.CommunityRepository;
import es.idynamicsax.ostris.service.CommitReceipt;
import es.idynamicsax.ostris.service.CommitTransactionCommand;
import es.idynamicsax.ostris.service.ProtocolEventProofService;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.function.Function;
import java.util.stream.Collectors;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;
@Service public class JournalCommitService {private final CommunityRepository communities;
private final AccountRepository accounts;
private final JdbcTemplate jdbc;
private final ProtocolEventProofService proofs;
private final ObjectMapper mapper;
private final OstrisWireCodec codec = new OstrisWireCodec();
public JournalCommitService(CommunityRepository communities, AccountRepository accounts, JdbcTemplate jdbc, ProtocolEventProofService proofs, ObjectMapper mapper) {this.communities = communities; this.accounts = accounts; this.jdbc = jdbc; this.proofs = proofs; this.mapper = mapper;}
@Transactional(isolation=Isolation.READ_COMMITTED) CommitReceipt commit(CommitTransactionCommand command, Set<UUID> governedAccounts) {List<TransactionEntry> entries = command.entries().stream().map(e -> new TransactionEntry(e.accountId(), OstrisAmount.parse(e.amount()))).toList(); TransactionValidator.validateBalanced(entries); this.validatePurpose(command); CommunityEntity community = this.communities.lock(command.communityId(), command.tenantId()).orElseThrow(() -> new ProtocolException("UNKNOWN_COMMUNITY", "Community not found")); List<UUID> ids = entries.stream().map(TransactionEntry::accountId).sorted().toList(); Map<UUID, AccountEntity> locked = this.accounts.lockAll(command.tenantId(), ids).stream().collect(Collectors.toMap(AccountEntity::getId, Function.identity())); if (locked.size() != ids.size()) {throw new ProtocolException("UNKNOWN_ACCOUNT", "Account not found");} Map<UUID, BigInteger> balances = this.reconstructBalances(command.tenantId(), command.communityId(), ids); this.validateSpecialAccounts(command, entries, locked, balances); for (TransactionEntry e2 : entries) {boolean enforced; AccountEntity a = locked.get(e2.accountId()); if (!a.getCommunityId().equals(command.communityId()) || !a.getUnitId().equals(command.unitId())) {throw new ProtocolException("ACCOUNT_SCOPE_MISMATCH", "All accounts must share community and unit");} BigInteger after = balances.get(e2.accountId()).add(e2.amount().minorUnits()); boolean bl = enforced = governedAccounts.contains(e2.accountId()) && (command.purpose() == TransactionPurpose.PENALTY || command.purpose() == TransactionPurpose.RESTITUTION); if (after.compareTo(a.getCreditFloor()) >= 0 || enforced) continue; throw new ProtocolException("CREDIT_FLOOR_EXCEEDED", "Credit floor exceeded for " + String.valueOf(a.getId()));} long sequence = community.allocateSequence(); this.validateFinalFinding(command, sequence); this.validateReversal(command, entries); ObjectNode payload = this.canonicalPayload(command, entries); byte[] canonical = this.codec.canonicalize((JsonNode)payload); String digest = OstrisWireCodec.sha256(canonical); Instant committed = Instant.now().truncatedTo(ChronoUnit.MICROS); try {this.jdbc.update("insert into ostris.journal_transaction(id,tenant_id,community_id,unit_id,community_sequence,purpose,references_json,policy_snapshot_json,canonical_json,protocol_digest,committed_at) values (?,?,?,?,?,?,?::jsonb,?::jsonb,?,?,?)", new Object[]{command.transactionId(), command.tenantId(), command.communityId(), command.unitId(), sequence, command.purpose().name(), this.json(command.references()), "{}", new String(canonical, StandardCharsets.UTF_8), digest, Timestamp.from(committed)});} catch (DuplicateKeyException ex) {throw new ProtocolException("DUPLICATE_TRANSACTION", "Transaction id or sequence already committed");} for (int i = 0; i < entries.size(); ++i) {TransactionEntry e3 = entries.get(i); this.jdbc.update("insert into ostris.journal_entry(transaction_id,entry_index,tenant_id,community_id,account_id,amount) values (?,?,?,?,?,?)", new Object[]{command.transactionId(), i, command.tenantId(), command.communityId(), e3.accountId(), e3.amount().minorUnits()}); locked.get(e3.accountId()).apply(e3.amount().minorUnits());} this.proofs.record(command.tenantId(), command.communityId(), command.transactionId(), digest); return new CommitReceipt(command.transactionId(), sequence, digest, committed);}
private void validatePurpose(CommitTransactionCommand c) {if (c.purpose() == TransactionPurpose.REVERSAL && !c.references().containsKey("reversesTransactionId")) {throw new ProtocolException("MISSING_ORIGINAL", "REVERSAL requires reversesTransactionId");} if (c.purpose() == TransactionPurpose.PENALTY && !c.references().containsKey("finalFindingId")) {throw new ProtocolException("MISSING_FINAL_FINDING", "PENALTY requires finalFindingId");} if (c.purpose() == TransactionPurpose.WRITE_OFF && !c.references().containsKey("defaultDecisionId")) {throw new ProtocolException("MISSING_DEFAULT_DECISION", "WRITE_OFF requires defaultDecisionId");} if (c.purpose() == TransactionPurpose.LOSS_OFFSET && !c.references().containsKey("governanceDecisionId")) {throw new ProtocolException("MISSING_GOVERNANCE_DECISION", "LOSS_OFFSET requires governanceDecisionId");} if (c.purpose() == TransactionPurpose.SETTLEMENT && Collections.disjoint(c.references().keySet(), Set.of("caseId", "agreementId", "settlesTransactionId"))) {throw new ProtocolException("MISSING_SETTLEMENT_REFERENCE", "SETTLEMENT requires caseId, agreementId or settlesTransactionId");}}
private void validateSpecialAccounts(CommitTransactionCommand c, List<TransactionEntry> entries, Map<UUID, AccountEntity> locked, Map<UUID, BigInteger> balances) {for (TransactionEntry e2 : entries) {String type = locked.get(e2.accountId()).getAccountType(); if (type.equals("COMMUNITY_PENALTY") && c.purpose() != TransactionPurpose.PENALTY && c.purpose() != TransactionPurpose.LOSS_OFFSET && c.purpose() != TransactionPurpose.REVERSAL) {throw new ProtocolException("SPECIAL_ACCOUNT_PURPOSE_FORBIDDEN", "CommunityPenaltyAccount forbidden for purpose");} if (!type.equals("COMMUNITY_LOSS") || c.purpose() == TransactionPurpose.WRITE_OFF || c.purpose() == TransactionPurpose.LOSS_OFFSET || c.purpose() == TransactionPurpose.REVERSAL) continue; throw new ProtocolException("SPECIAL_ACCOUNT_PURPOSE_FORBIDDEN", "CommunityLossAccount forbidden for purpose");} if (c.purpose() == TransactionPurpose.PENALTY) {if (entries.size() != 2) {throw new ProtocolException("INVALID_SPECIAL_ACCOUNT_SHAPE", "PENALTY requires sanctioned and penalty entries");} this.requireSpecialShape(entries, locked, "COMMUNITY_PENALTY", 1);} if (c.purpose() == TransactionPurpose.LOSS_OFFSET) {if (entries.size() != 2) {throw new ProtocolException("INVALID_SPECIAL_ACCOUNT_SHAPE", "LOSS_OFFSET requires exactly penalty and loss entries");} this.requireSpecialShape(entries, locked, "COMMUNITY_PENALTY", -1); this.requireSpecialShape(entries, locked, "COMMUNITY_LOSS", 1);} if (c.purpose() == TransactionPurpose.WRITE_OFF) {this.requireSpecialShape(entries, locked, "COMMUNITY_LOSS", -1); if (entries.size() != 2) {throw new ProtocolException("INVALID_WRITE_OFF", "WRITE_OFF requires exactly two entries");} TransactionEntry subject = entries.stream().filter(e -> ((AccountEntity)locked.get(e.accountId())).getAccountType().equals("INDIVIDUAL") || ((AccountEntity)locked.get(e.accountId())).getAccountType().equals("ORGANIZATION")).findFirst().orElseThrow(() -> new ProtocolException("INVALID_WRITE_OFF", "Missing defaulted account")); AccountEntity account = locked.get(subject.accountId()); BigInteger balance = balances.get(subject.accountId()); if (!account.getRiskState().equals("DEFAULTED") || balance.signum() >= 0 || !subject.amount().minorUnits().equals(balance.negate())) {throw new ProtocolException("INVALID_WRITE_OFF", "WRITE_OFF must fully zero one DEFAULTED negative account");}}}
private Map<UUID, BigInteger> reconstructBalances(UUID tenant, UUID community, List<UUID> ids) {HashMap<UUID, BigInteger> balances = new HashMap<UUID, BigInteger>(); ids.forEach(id -> balances.put((UUID)id, BigInteger.ZERO)); this.jdbc.query("select e.account_id,coalesce(sum(e.amount),0) from ostris.journal_entry e join ostris.journal_transaction t on t.id=e.transaction_id where e.tenant_id=? and e.community_id=? and t.status='COMMITTED' group by e.account_id", rs -> {UUID id = rs.getObject(1, UUID.class); if (balances.containsKey(id)) {balances.put(id, rs.getBigDecimal(2).toBigIntegerExact());}}, new Object[]{tenant, community}); return balances;}
private void requireSpecialShape(List<TransactionEntry> entries, Map<UUID, AccountEntity> locked, String type, int sign) {List<TransactionEntry> matches = entries.stream().filter(e -> ((AccountEntity)locked.get(e.accountId())).getAccountType().equals(type)).toList(); if (matches.size() != 1 || matches.getFirst().amount().minorUnits().signum() != sign) {throw new ProtocolException("INVALID_SPECIAL_ACCOUNT_SHAPE", "Required special-account entry/sign missing");}}
private void validateFinalFinding(CommitTransactionCommand c, long sequence) {if (c.purpose() != TransactionPurpose.PENALTY && (c.purpose() != TransactionPurpose.RESTITUTION || c.resolutionBasisType() != ResolutionBasisType.FINAL_FINDING)) {return;} UUID finding = UUID.fromString(c.references().get("finalFindingId")); Integer n = (Integer)this.jdbc.queryForObject("select count(*) from ostris.finding where id=? and tenant_id=? and community_id=? and status='FINAL' and finality_sequence<?", Integer.class, new Object[]{finding, c.tenantId(), c.communityId(), sequence}); if (n == null || n != 1) {throw new ProtocolException("FINDING_NOT_FINAL", "Final finding not effective");}}
private void validateReversal(CommitTransactionCommand c, List<TransactionEntry> entries) {if (c.purpose() != TransactionPurpose.REVERSAL) {return;} UUID originalId = UUID.fromString(c.references().get("reversesTransactionId")); List original = this.jdbc.query("select purpose from ostris.journal_transaction where id=? and tenant_id=?", (rs, row) -> rs.getString(1), new Object[]{originalId, c.tenantId()}); if (original.size() != 1) {throw new ProtocolException("REVERSAL_INVALID", "Original not found");} if ("REVERSAL".equals(original.getFirst())) {throw new ProtocolException("REVERSAL_INVALID", "Cannot reverse reversal");} Integer previous = (Integer)this.jdbc.queryForObject("select count(*) from ostris.journal_transaction where purpose='REVERSAL' and references_json->>'reversesTransactionId'=?", Integer.class, new Object[]{originalId.toString()}); if (previous != null && previous > 0) {throw new ProtocolException("REVERSAL_INVALID", "Already reversed");} List expected = this.jdbc.query("select account_id,amount from ostris.journal_entry where transaction_id=? order by entry_index", (rs, row) -> new TransactionEntry(rs.getObject(1, UUID.class), new OstrisAmount(rs.getBigDecimal(2).toBigIntegerExact())), new Object[]{originalId}); TransactionValidator.validateFullReversal(new JournalTransaction(1L, TransactionPurpose.valueOf((String)original.getFirst()), expected), entries, previous == null ? 0L : (long)previous.intValue());}
private ObjectNode canonicalPayload(CommitTransactionCommand c, List<TransactionEntry> entries) {ObjectNode n = this.mapper.createObjectNode(); n.put("wireFormat", "OSTRIS-CORE-JCS-1"); n.put("unitId", c.unitId().toString()); n.put("transactionId", c.transactionId().toString()); ObjectNode refs = n.putObject("references"); c.references().entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e -> refs.put((String)e.getKey(), (String)e.getValue())); n.put("purpose", c.purpose().name()); n.put("ostrisCoreVersion", "0.1"); ArrayNode a = n.putArray("entries"); for (TransactionEntry e2 : entries) {ObjectNode x = a.addObject(); x.put("accountId", e2.accountId().toString()); x.put("amount", e2.amount().wire());} n.put("communityId", c.communityId().toString()); if (c.contractualMetadataDigest() != null) {n.put("contractualMetadataDigest", c.contractualMetadataDigest());} if (c.resolutionBasisType() != null) {ObjectNode rb = n.putObject("resolutionBasis"); rb.put("id", c.resolutionBasisId().toString()); rb.put("type", c.resolutionBasisType().name());} return n;}
private String json(Object value) {try {return this.mapper.writeValueAsString(value);} catch (Exception e) {throw new IllegalStateException(e);}}
}
